const G=require('./dist/geometry.js'),assert=require('assert');let checks=0;
for(const angle of [0,12.5,37,90,-44]){let p=G.rectangle([-3,-3],[3,3],angle);assert(p&&G.valid(p));for(let i=0;i<4;i++){let a=p[i],b=p[(i+1)%4],c=p[(i+2)%4],dot=(a[0]-b[0])*(c[0]-b[0])+(a[1]-b[1])*(c[1]-b[1]);assert(Math.abs(dot)<1e-8);checks++}let q=G.moveEdge(p,0,-.2);assert(q&&G.valid(q));for(let i=0;i<4;i++){let a=q[i],b=q[(i+1)%4],c=q[(i+2)%4];assert(Math.abs((a[0]-b[0])*(c[0]-b[0])+(a[1]-b[1])*(c[1]-b[1]))<1e-8);checks++}let b=G.orthEnd([0,0],[2,1],angle),v=G.local(b,angle);assert(Math.abs(v[0])<1e-8||Math.abs(v[1])<1e-8);checks++}
let p=[[-1,-1],[1,-1],[1,1],[-1,1]],q=G.moveEdge(p,1,-.5);assert.equal(G.area(q),5);checks++;let ops=[{type:'rectangle',a:[-2,-2],b:[2,2],angle:0},{type:'edge_move',index:1,offset:-1},{type:'cut',a:[-1,-4],b:[-1,4],side:-1}];assert(G.valid(G.replay(p,ops)));checks++;assert.equal(G.moveEdge(p,8,1),null);checks++;assert.equal(G.replay(p,[{type:'invented'}]),null);checks++;
console.log('geometry v2 checks:',checks);
